Tests.EqualCheck("highlight multiple occurrences of word", "\033[31mapple\033[0m and \033[31mapple\033[0m", highlightAllMatches("apple and apple", "apple"))
Tests.EqualCheck("highlight all numbers in line", "ports \033[31m8080\033[0m, \033[31m8443\033[0m, \033[31m9000\033[0m", highlightAllMatches("ports 8080, 8443, 9000", `\d+`))
Tests.EqualCheck("highlight multiple alternation branches", "\033[31mcat\033[0m and \033[31mdog\033[0m", highlightAllMatches("cat and dog", "cat|dog"))
Tests.EqualCheck("highlight non-overlapping sequences", "\033[31maa\033[0m\033[31maa\033[0m", highlightAllMatches("aaaa", "aa"))
Tests.EqualCheck("no match returns original string", "no numbers here", highlightAllMatches("no numbers here", `\d+`))
Tests.EqualCheck("empty pattern returns original string", "original text", highlightAllMatches("original text", ""))
Tests.EqualCheck("empty line returns empty line", "", highlightAllMatches("", "word"))
Tests.EqualCheck("highlight three character class matches", "code \033[31m[A]\033[0m, \033[31m[B]\033[0m, \033[31m[C]\033[0m", highlightAllMatches("code [A], [B], [C]", `\[[A-Z]\]`))
Tests.EqualCheck("highlight single character matches", "\033[31ma\033[0m b \033[31ma\033[0m c \033[31ma\033[0m", highlightAllMatches("a b a c a", "a"))
Tests.EqualCheck("start anchor matches only at beginning", "\033[31mstart\033[0m not start", highlightAllMatches("start not start", "^start"))
Tests.EqualCheck("end anchor matches only at end", "end not \033[31mend\033[0m", highlightAllMatches("end not end", "end$"))
Tests.EqualCheck("highlight multiple backreferences", "\033[31mcat and cat\033[0m plus \033[31mdog and dog\033[0m", highlightAllMatches("cat and cat plus dog and dog", `(\w+) and \1`))
Tests.EqualCheck("highlight words matching quantifier range", "\033[31mabc\033[0m or \033[31mdefgh\033[0m", highlightAllMatches("abc or defgh", `\w{3,5}`))
Tests.EqualCheck("highlight consecutive digits separated by non-digits", "v\033[31m1\033[0m.\033[31m2\033[0m.\033[31m3\033[0m", highlightAllMatches("v1.2.3", `\d`))
Tests.EqualCheck("line with no occurrences unchanged", "abcdef", highlightAllMatches("abcdef", "123"))
Tests.EqualCheck("highlight whitespace characters", "a\033[31m  \033[0mb", highlightAllMatches("a  b", ` {2}`))
